class AppConfig extends InheritedWidget {
  const AppConfig({super.key, required this.env, required super.child});
  final String env;

  static AppConfig of(BuildContext c) =>
      c.dependOnInheritedWidgetOfExactType<AppConfig>()!;

  @override
  bool updateShouldNotify(AppConfig old) => env != old.env;
}

